window.RI2_UNITS = {"2":{"unit":2,"code":"RI2-U02","title":"CALL OF THE WILD","startNumber":34,"endNumber":64,"entries":[{"number":34,"term":"light-hearted","sourceTerm":"light-hearted (a)","spoken":"light-hearted","ipa":"light-hearted /ˌlaɪtˈhɑːrtɪd/","type":"adjective","meaning":"nhẹ nhàng, vui vẻ (một câu chuyện…)","definition":"Amusing, cheerful, and not serious or emotionally heavy.","note":"","example":"The documentary begins with a light-hearted story about a playful dolphin."},{"number":35,"term":"school of fish","sourceTerm":"school of fish","spoken":"school of fish","ipa":"school /skuːl/ · fish /fɪʃ/","type":"word / phrase","meaning":"đàn cá","definition":"A large group of fish swimming together.","note":"A school of fish chỉ một đàn cá. School trong cụm này không mang nghĩa trường học.","example":"A school of fish changed direction as soon as the shark approached."},{"number":36,"term":"marine · marine life","sourceTerm":"marine · marine life","spoken":"marine , marine life","ipa":"marine /mɚˈiːn/ · life /laɪf/","type":"noun · adjective","meaning":"thuộc về biển · sinh vật biển, sự sống dưới biển","definition":"Related to the sea; marine life includes the plants and animals that live there.","note":"Marine + danh từ: marine biology, marine species, marine environment.","example":"The protected bay supports rich marine life, including turtles and coral."},{"number":37,"term":"curious · curiosity","sourceTerm":"curious · curiosity","spoken":"curious , curiosity","ipa":"curious /ˈkjʊriəs/ · curiosity /ˌkjʊriˈɑːsəti/","type":"noun · adjective","meaning":"tò mò, muốn biết · sự tò mò","definition":"Eager to know or learn about something; curiosity is that desire to know.","note":"Curious about sth chỉ sự tò mò về điều gì. Curious còn có thể mang nghĩa lạ lùng tùy văn cảnh.","example":"The curious young whale approached the boat, and its curiosity surprised the researchers."},{"number":38,"term":"extend · extension · extensive","sourceTerm":"extend · extension · extensive","spoken":"extend , extension , extensive","ipa":"extend /ɪˈkstɛnd/ · extension /ɪˈkstɛnʃən/ · extensive /ɪˈkstɛnsɪv/","type":"verb · noun · adjective","meaning":"mở rộng, kéo dài · sự mở rộng; phần được nối thêm · rộng lớn, bao quát","definition":"To make something longer or larger; an extension is the added part or act, and extensive means covering a large area or range.","note":"Extend là động từ. Extension là danh từ. Extensive mô tả phạm vi rộng, không phải “có thể kéo dài”.","example":"The government extended the reserve, and this extension now protects an extensive area of ocean."},{"number":39,"term":"anthem","sourceTerm":"anthem (n)","spoken":"anthem","ipa":"anthem /ˈænθəm/","type":"noun","meaning":"quốc ca","definition":"A formal song that represents a nation, organization, or shared cause.","note":"National anthem chỉ quốc ca. Anthem cũng có thể là bài hát biểu tượng của một nhóm hoặc phong trào.","example":"Students stood quietly while the national anthem was played."},{"number":40,"term":"breed","sourceTerm":"breed (v)","spoken":"breed","ipa":"breed /briːd/","type":"verb","meaning":"sinh sản; giao phối (động vật)","definition":"For animals to reproduce; also to keep animals in order to produce young with chosen qualities.","note":"Breed – bred – bred. Breed còn là danh từ chỉ giống vật nuôi.","example":"Sea turtles breed on the same beaches where they were born."},{"number":41,"term":"approach","sourceTerm":"approach (v) · (n)","spoken":"approach","ipa":"approach /əˈproʊtʃ/","type":"verb · noun","meaning":"đến gần, tiếp cận · cách tiếp cận, phương pháp","definition":"To move nearer to someone or something; also a method of dealing with a subject or problem.","note":"Approach + tân ngữ khi là động từ, không dùng approach to. An approach to + danh từ khi là danh từ.","example":"The team approached the animals slowly and used a gentle approach to collect data."},{"number":42,"term":"desire","sourceTerm":"desire (v,n)","spoken":"desire","ipa":"desire /dɪˈzaɪɚ/","type":"verb · noun","meaning":"khao khát, mong ước","definition":"A strong wish to have something or make something happen.","note":"Desire to do sth. A desire for sth. Desire mang sắc thái trang trọng và thường thể hiện mong muốn mạnh.","example":"Many people desire closer contact with wildlife, but that desire must not disturb the animals."},{"number":43,"term":"migrate · migration ~ immigrate · immigrant","sourceTerm":"migrate · migration ~ immigrate · immigrant","spoken":"migrate , migration , immigrate , immigrant","ipa":"migrate /ˈmaɪˌɡreɪt/ · migration /maɪˈɡreɪʃən/ · immigrate /ˈɪməˌɡreɪt/ · immigrant /ˈɪməɡrənt/","type":"verb · verb · noun · noun","meaning":"di cư · sự di cư ~ nhập cư vào một quốc gia · người nhập cư","definition":"To migrate is to move between regions; migration is that movement, while to immigrate is to enter a country to live there and an immigrant is the person who does so.","note":"Animals and people migrate. Immigrate chỉ người đi vào một quốc gia để sinh sống.","example":"Whales migrate north each year, but people may immigrate permanently; each immigrant becomes part of a wider pattern of human migration."},{"number":44,"term":"mimic ~ imitate ~ copy","sourceTerm":"mimic (v) ~ imitate (v) ~ copy (v)","spoken":"mimic , imitate , copy","ipa":"mimic /ˈmɪmɪk/ · imitate /ˈɪməˌteɪt/ · copy /ˈkɑːpi/","type":"verb · verb · verb","meaning":"bắt chước","definition":"To reproduce another person's or animal's sound, action, or behavior.","note":"Mimic thường nhấn mạnh bắt chước rất giống âm thanh hoặc cử chỉ. Imitate trung tính. Copy dùng rộng hơn.","example":"Some birds mimic human speech, while young animals imitate adults and copy useful behavior."},{"number":45,"term":"accurate >< inaccurate · accuracy >< inaccuracy","sourceTerm":"accurate >< inaccurate · accuracy >< inaccuracy","spoken":"accurate , inaccurate , accuracy , inaccuracy","ipa":"accurate /ˈækjɚət/ · inaccurate /ˌɪˈnækjɚət/ · accuracy /ˈækjɚəsi/ · inaccuracy /ˌɪˈnækjɚəsi/","type":"noun · noun · adjective · adjective","meaning":"chính xác · không chính xác · độ chính xác · sự thiếu chính xác","definition":"Correct and exact; accuracy is the degree of correctness, while inaccurate and inaccuracy express the opposite.","note":"Dùng accurate khi thông tin hoặc kết quả đúng với thực tế. Dạng phủ định thêm tiền tố in-.","example":"Accurate recordings improve the accuracy of the study, whereas inaccurate labels create serious errors."},{"number":46,"term":"reveal · revelation >< conceal","sourceTerm":"reveal · revelation >< conceal","spoken":"reveal , revelation , conceal","ipa":"reveal /rɪˈviːl/ · revelation /ˌrɛvəˈleɪʃən/ · conceal /kəˈnsiːl/","type":"verb · verb · noun","meaning":"tiết lộ · sự tiết lộ; điều được tiết lộ · che giấu","definition":"To make previously hidden information known; a revelation is what is disclosed, while conceal means to keep it hidden.","note":"Reveal sth to sb. Conceal sth from sb.","example":"The recordings revealed a new call pattern, and this revelation challenged the idea that dolphins conceal all signs of stress."},{"number":47,"term":"aspect · aspect of life","sourceTerm":"aspect · aspect of life","spoken":"aspect , aspect of life","ipa":"aspect /ˈæˌspɛkt/ · life /laɪf/","type":"noun · noun","meaning":"khía cạnh · khía cạnh của cuộc sống","definition":"One particular feature or part of a situation, subject, or life.","note":"An aspect of + danh từ. Aspect không có nghĩa là toàn bộ vấn đề.","example":"Communication is an important aspect of social life among whales."},{"number":48,"term":"evolve · evolution","sourceTerm":"evolve · evolution","spoken":"evolve , evolution","ipa":"evolve /ɪˈvɑːlv/ · evolution /ˌɛvəˈluːʃən/","type":"verb · noun","meaning":"tiến hóa, phát triển dần · sự tiến hóa, quá trình phát triển","definition":"To develop gradually over generations or over time; evolution is this process of change.","note":"Evolve nhấn mạnh sự thay đổi dần qua thời gian hoặc qua nhiều thế hệ.","example":"Whale songs may evolve as groups interact, and their evolution can be traced through recordings."},{"number":49,"term":"organism","sourceTerm":"organism (n)","spoken":"organism","ipa":"organism /ˈɔːrɡəˌnɪzəm/","type":"noun","meaning":"sinh vật","definition":"An individual living thing, such as an animal, plant, fungus, or bacterium.","note":"","example":"Each organism responds differently to changes in water temperature."},{"number":50,"term":"local dialect # accent","sourceTerm":"local dialect # accent","spoken":"local dialect , accent","ipa":"local /ˈloʊkəl/ · dialect /ˈdaɪəˌlɛkt/ · accent /əˈksɛnt/","type":"noun · noun","meaning":"phương ngữ địa phương · giọng, cách phát âm","definition":"A local dialect is a regional form of a language involving vocabulary and grammar; an accent is mainly a way of pronouncing words.","note":"Dialect gồm khác biệt về từ vựng, ngữ pháp và phát âm. Accent chủ yếu nói về phát âm.","example":"Researchers compared each whale group's calls to a local dialect rather than just a different accent."},{"number":51,"term":"perhaps ~ possibly ~ probably","sourceTerm":"perhaps ~ possibly ~ probably","spoken":"perhaps , possibly , probably","ipa":"perhaps /pɚˈhæps/ · possibly /ˈpɑːsəbli/ · probably /ˈprɑːbəˌbli/","type":"adverb · adverb · adverb","meaning":"có lẽ, có thể ~ có lẽ, nhiều khả năng","definition":"Perhaps and possibly express uncertainty; probably suggests that something is more likely than not.","note":"Probably thể hiện khả năng cao hơn perhaps/possibly. Không xem ba từ là hoàn toàn tương đương.","example":"The dolphins perhaps learned the call from adults, possibly through play, and probably used it to remain together."},{"number":52,"term":"present · presence >< absent · absence","sourceTerm":"present · presence >< absent · absence","spoken":"present , presence , absent , absence","ipa":"present /ˈprɛzənt/ · presence /ˈprɛzəns/ · absent /ˈæbsənt/ · absence /ˈæbsəns/","type":"noun · noun · adjective · adjective","meaning":"có mặt · sự hiện diện · vắng mặt · sự vắng mặt","definition":"Present means being in a place; presence is the state of being there, while absent and absence express not being there.","note":"Be present/absent at an event. Presence/absence of + danh từ.","example":"Adult whales were present during the test, and their presence made the young animals calmer; when adults were absent, signs of stress increased."},{"number":53,"term":"interact · interaction","sourceTerm":"interact · interaction","spoken":"interact , interaction","ipa":"interact /ˌɪntɚˈækt/ · interaction /ˌɪntɚˈækʃən/","type":"verb · noun","meaning":"tương tác · sự tương tác","definition":"To communicate or act in relation to one another; an interaction is an occasion or process of doing so.","note":"Interact with + người/vật. Interaction between A and B hoặc interaction with sb.","example":"Young dolphins interact through play, and each interaction helps them learn social signals."},{"number":54,"term":"appear to do sth · apparent","sourceTerm":"appear to do sth · apparent","spoken":"appear to do something , apparent","ipa":"appear /əˈpɪr/ · apparent /əˈpɛrənt/","type":"verb · adjective · phrase / pattern","meaning":"dường như, có vẻ làm gì · có vẻ; rõ ràng, dễ nhận thấy","definition":"To seem to do or be something; apparent means seeming true or clearly visible from the evidence.","note":"Appear to do sth diễn tả điều dường như xảy ra. Apparent có thể là “có vẻ” chứ chưa chắc đã đúng trên thực tế.","example":"The animal appeared to recognize its name, but the apparent response required further testing."},{"number":55,"term":"complex ~ complicated >< simple","sourceTerm":"complex ~ complicated >< simple","spoken":"complex , complicated , simple","ipa":"complex /ˈkɑːmplɛks/ · complicated /ˈkɑːmpləˌkeɪtəd/ · simple /ˈsɪmpəl/","type":"adjective · adjective · adjective","meaning":"phức tạp · đơn giản","definition":"Complex or complicated has many connected parts and is difficult to understand; simple expresses the opposite.","note":"Complex thường trung tính, nhấn mạnh nhiều phần liên kết. Complicated thường nhấn mạnh khó hiểu hoặc khó xử lí.","example":"A whale's call system is complex, but one simple signal may carry a clear warning."},{"number":56,"term":"giant ~ huge","sourceTerm":"giant (a, n) ~ huge (a)","spoken":"giant , huge","ipa":"giant /ˈdʒaɪənt/ · huge /hjuːdʒ/","type":"noun · adjective · adjective","meaning":"khổng lồ; vật/người khổng lồ","definition":"Extremely large; giant can also be a noun for a very large person, animal, or organization.","note":"Giant có thể đứng trước danh từ hoặc dùng như danh từ. Huge chỉ là tính từ.","example":"The blue whale is a giant of the ocean, with a huge body adapted for long migrations."},{"number":57,"term":"potential","sourceTerm":"potential (a, n)","spoken":"potential","ipa":"potential /pəˈtɛnʃəl/","type":"noun · adjective","meaning":"tiềm năng; khả năng tiềm ẩn","definition":"The ability or possibility to develop, succeed, or produce a future result.","note":"Potential to do sth. Potential for sth. Potential có thể là danh từ hoặc tính từ.","example":"The discovery has the potential to change how scientists understand animal language."},{"number":58,"term":"isolate","sourceTerm":"isolate (v)","spoken":"isolate","ipa":"isolate /ˈaɪsəˌleɪt/","type":"verb","meaning":"cô lập, cách li…","definition":"To separate a person, animal, or thing from others, often for study or protection.","note":"Isolate A from B. Isolated mô tả trạng thái bị tách biệt hoặc ở nơi xa xôi.","example":"Scientists did not isolate the dolphin because separation could alter its behavior."},{"number":59,"term":"strategy ~ tactic","sourceTerm":"strategy ~ tactic","spoken":"strategy , tactic","ipa":"strategy /ˈstrætədʒi/ · tactic /ˈtæktɪk/","type":"noun · noun","meaning":"chiến lược, kế hoạch tổng thể ~ chiến thuật, hành động cụ thể","definition":"A strategy is an overall plan for achieving an aim; a tactic is one specific action used within that plan.","note":"Strategy là kế hoạch tổng thể. Tactic là hành động cụ thể trong kế hoạch đó.","example":"The pod's hunting strategy involved a tactic in which two whales drove fish toward the group."},{"number":60,"term":"stable · stability","sourceTerm":"stable · stability","spoken":"stable , stability","ipa":"stable /ˈsteɪbəl/ · stability /stəˈbɪlɪti/","type":"noun · adjective","meaning":"ổn định, ít biến động · sự ổn định","definition":"Not likely to change, fail, or move suddenly; stability is the condition of being stable.","note":"Stable có thể mô tả số lượng, hệ thống, tình trạng hoặc cấu trúc ít biến động.","example":"A stable habitat supports long-term population stability."},{"number":61,"term":"longevity ~ life expectancy","sourceTerm":"longevity ~ life expectancy","spoken":"longevity , life expectancy","ipa":"longevity /lɔˈndʒɛvəti/ · life /laɪf/ · expectancy /ɪˈkspɛktənsi/","type":"noun · noun","meaning":"tuổi thọ cao; sự trường thọ ~ tuổi thọ dự tính","definition":"Longevity is a long life or long existence; life expectancy is the statistically expected length of life.","note":"Longevity nhấn mạnh thời gian tồn tại dài. Life expectancy là tuổi thọ dự tính theo thống kê.","example":"Researchers study whale longevity, while population data help them estimate life expectancy."},{"number":62,"term":"standard","sourceTerm":"standard (n,a)","spoken":"standard","ipa":"standard /ˈstændɚd/","type":"noun · adjective","meaning":"tiêu chuẩn, chuẩn mực; đạt chuẩn","definition":"An accepted level of quality or behavior; as an adjective, meeting an ordinary accepted level.","note":"Meet a standard. Set/raise standards. Standard không nhất thiết mang nghĩa xuất sắc.","example":"The team followed an international standard and used standard recording equipment."},{"number":63,"term":"barrier ~ obstacle","sourceTerm":"barrier (n) ~ obstacle (n)","spoken":"barrier , obstacle","ipa":"barrier /ˈbæriɚ/ · obstacle /ˈɑːbstəkəl/","type":"noun · noun","meaning":"rào cản; chướng ngại vật","definition":"Something that blocks movement, communication, or progress.","note":"Barrier thường là vật hoặc yếu tố ngăn cách. Obstacle là khó khăn phải vượt qua trên đường đạt mục tiêu.","example":"Distance is a major barrier to observation, while bad weather creates an additional obstacle."},{"number":64,"term":"habitat","sourceTerm":"habitat (n)","spoken":"habitat","ipa":"habitat /ˈhæbəˌtæt/","type":"noun","meaning":"môi trường sống (động thực vật)","definition":"The natural environment in which a particular plant or animal lives.","note":"Dùng habitat cho nơi sống tự nhiên của một loài, không phải môi trường theo nghĩa rộng.","example":"Noise from ships can disturb the natural habitat of marine mammals."}],"pronunciationFocus":[{"entryNumber":35,"points":[{"category":"linking","note":"Đọc liền school‿of, nối /l/ cuối school sang nguyên âm đầu của of"}]},{"entryNumber":37,"points":[{"category":"word-stress","note":"curious nhấn âm đầu; curiosity chuyển trọng âm sang âm tiết chứa /ɑː/"}]},{"entryNumber":38,"points":[{"category":"word-stress","note":"extend, extension và extensive đều nhấn âm tiết thứ hai"},{"category":"final-sound","note":"extend kết thúc bằng /nd/; extension có phần cuối /nʃən/"}]},{"entryNumber":43,"points":[{"category":"word-stress","note":"migrate và immigrate nhấn âm đầu; migration chuyển trọng âm sang âm tiết chứa /eɪ/"}]},{"entryNumber":47,"points":[{"category":"final-sound","note":"aspect kết thúc bằng cụm /kt/; giữ đủ hai phụ âm cuối"}]},{"entryNumber":53,"points":[{"category":"word-stress","note":"interact và interaction đều nhấn vào âm tiết chứa /æk/"},{"category":"final-sound","note":"interact kết thúc bằng cụm /kt/"}]},{"entryNumber":61,"points":[{"category":"word-stress","note":"longevity nhấn âm tiết thứ hai; expectancy cũng nhấn âm tiết thứ hai"}]}]}};
